def solid_cols(grid):
    """Indices of columns that are one color throughout."""
    return [c for c in range(len(grid[0])) if len({row[c] for row in grid}) == 1]

def blocks(grid):
    """(row_spans, col_spans): the start-end ranges of cell blocks between one-color separator rows/columns."""
    rseps, cseps = solid_rows(grid), solid_cols(grid)
    H, W = len(grid), len(grid[0])
    rb = [r for r in range(H) if r not in rseps and (r == 0 or r - 1 in rseps)]
    cb = [c for c in range(W) if c not in cseps and (c == 0 or c - 1 in cseps)]
    rseps, cseps = rseps + [H], cseps + [W]
    rspan = {r0: min(s for s in rseps if s > r0) for r0 in rb}
    cspan = {c0: min(s for s in cseps if s > c0) for c0 in cb}
