def block_cells(grid):
    """Every cell block as {(top, left): subgrid}, blocks being the regions between separators."""
    (rb, rspan), (cb, cspan) = blocks(grid)
    return {(r0, c0): [row[c0:cspan[c0]] for row in grid[r0:rspan[r0]]] for r0 in rb for c0 in cb}

def recolor_cells(grid, pattern, color):
    """Every cell replaced by `pattern` with its nonzero cells colored `color`; separators and grid shape kept."""
    (rb, rspan), (cb, cspan) = blocks(grid)
