            out.append([sep] * W); continue
        r0 = max(x for x in rb if x <= r)
        row = []
        for c in range(W):
            if c in cspan and c not in cb:
                row.append(sep)
            else:
                c0 = max(x for x in cb if x <= c)
                row.append(color if pattern[r - r0][c - c0] != 0 else 0)
        out.append(row)
    return out

def nones(grid, blk):
    """The nonzero colors of a cell block."""
    return {v for row in blk for v in row if v != 0}

